#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

int numOfSubarrays(int* arr, int arrSize) {
    const long long MOD = 1000000007LL;
    long long even = 1, odd = 0, ans = 0;
    int parity = 0;
    for (int i = 0; i < arrSize; ++i) {
        parity ^= (arr[i] & 1);
        if (parity) { ans = (ans + even) % MOD; ++odd; }
        else { ans = (ans + odd) % MOD; ++even; }
    }
    return (int)ans;
}

