        s=s.substring(1,s.length()-1);
        List<String> parts=new ArrayList<>(); int depth=0,start=0;
        for(int i=0;i<s.length();i++){ char c=s.charAt(i); if(c=='[') depth++; else if(c==']') depth--; else if(c==','&&depth==0){parts.add(s.substring(start,i).trim()); start=i+1;} }
