        return parts.toArray(new String[0]);
    }
    static int[] toIntArray(String s){ String[] p=readArrayRaw(s); int[] a=new int[p.length]; for(int i=0;i<p.length;i++) a[i]=Integer.parseInt(p[i]); return a; }
